class School:
    def __init__(self):
        self._students = {}
        self._enrolled = set()
        self._added_log = []

    def add_student(self, name, grade):
        if name in self._enrolled:
            self._added_log.append(False)
            return False
        self._students.setdefault(grade, []).append(name)
        self._enrolled.add(name)
        self._added_log.append(True)
        return True

    def roster(self):
        return [
            name
            for grade in sorted(self._students)
            for name in sorted(self._students[grade])
        ]

    def grade(self, grade_number):
        return sorted(self._students.get(grade_number, []))

    def added(self):
        return list(self._added_log)
